import itertools as it, math, json, pathlib, hashlib, html, re
from fractions import Fraction as F
from collections import Counter

ROOT=pathlib.Path(__file__).parent
targets=json.loads((ROOT/'reasoning_targets.json').read_text())
out=[]
buckets={p:[x for x in targets if x['current']['topic']==p] for p in {x['current']['topic'] for x in targets}}
def fmt(x):
    if isinstance(x,F): return str(x.numerator) if x.denominator==1 else rf'\frac{{{x.numerator}}}{{{x.denominator}}}'
    return str(x)
def add(topic,sub,family,stem,ans,wrong,sol,oracle=None,difficulty=3,method='Exact enumeration and a complete counting argument'):
    t=buckets[topic].pop(0); n=len(out); values=[ans]+list(wrong)
    assert len(values)==5 and len(set(map(str,values)))==5,(family,values)
    if oracle is not None: assert ans==oracle,(family,ans,oracle)
    correct=n%5; values.insert(correct,values.pop(0)); lab='ABCDE'[correct]
    numeric=all(isinstance(x,(int,F)) for x in values)
    opts=[{'label':L,'html':r'\('+fmt(v)+r'\)' if numeric else str(v)} for L,v in zip('ABCDE',values)]
    def safe(s):
        return re.sub(r'\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]',lambda m:m[0].replace('<','&lt;').replace('>','&gt;'),s)
    prompt=safe('<p>'+stem+'</p>'); solution=safe('<p>'+sol+'</p>')
    out.append({'qid':t['Portal question ID'],'app_number':t['Portal number'],'paper':int(re.search(r'-P([12])',t['Legacy release ID'])[1]),'topic':topic,'subtopic':sub,'difficulty':difficulty,'tags':[sub.lower(),family.replace('_',' ')],'prompt_html':prompt,'options':[{**o,'html':safe(o['html'])} for o in opts],'answer':lab,'solution_html':solution,'family':family,'validation':{'method':method,'details':'The stated domain is used throughout the worked proof. '+('An independent exhaustive enumeration agrees with the derived answer.' if oracle is not None else 'Each alternative is resolved by the explicit proof or counterexample in the solution.')},'skills':[sub,'Domain restrictions','Verify the conclusion'],'old_prompt_sha256':hashlib.sha256(t['current']['prompt_html'].encode()).hexdigest()})
    (ROOT/'reasoning_questions.partial.json').write_text(json.dumps(out,indent=2,ensure_ascii=False))
def count(stem,ans,wrong,sol,oracle,fam,sub='Counting with restrictions',d=3):add('10_Miscellaneous',sub,fam,stem,ans,wrong,sol,oracle,d)
C=math.comb; fact=math.factorial

# Fifty distinct counting tasks. Exhaustive checks use the objects themselves,
# independently of the counting formula in the worked solution.
for n in [7,9]:
    a=C(n-2,3); brute=sum(sum(v)==3 and all(not(v[i] and v[i+1]) for i in range(n-1)) for v in it.product([0,1],repeat=n))
    count(rf'A row has \({n}\) numbered lamps. Exactly three are lit, and no two lit lamps are adjacent. How many lighting patterns are possible?',a,[C(n,3),a-1,a+1,C(n-1,3)],rf'Write the lit positions as \(i<j<k\), with gaps at least two. The map \((i,j,k)\mapsto(i,j-1,k-2)\) is a bijection to three-element subsets of \(\{{1,\ldots,{n-2}\}}\). The count is \(\binom{{{n-2}}}3={a}\).',brute,'separated_lamps')
for n in [8,10]:
    a=3*C(n-3,2); brute=sum(sum(v)==4 and sum(v[i] and (i==0 or not v[i-1]) for i in range(n))==2 for v in it.product([0,1],repeat=n))
    count(rf'A binary string of length \({n}\) contains four 1s in exactly two nonempty blocks. A block is a maximal consecutive run of 1s. How many such strings exist?',a,[a//3,2*a,a+3,3*C(n-4,2)],rf'The four 1s split into two positive block lengths in three ways. Of the \({n-4}\) zeros, one separates the blocks. Distribute the remaining \({n-5}\) zeros before, between and after them in \(\binom{{{n-3}}}2\) ways. Thus the count is \(3\binom{{{n-3}}}2={a}\).',brute,'two_runs')
for N in [8,11]:
    a=sum((N-3*z)//2+1 for z in range(N//3+1)); brute=sum(x+2*y+3*z==N for x,y,z in it.product(range(N+1),repeat=3))
    count(rf'A machine makes a batch of size \({N}\) using packs of sizes 1, 2 and 3. Packs of the same size are indistinguishable. How many triples of pack counts can produce the batch?',a,[a-2,a+2,N+1,C(N+2,2)],rf'Fix the number \(z\) of size-3 packs. For \(0\le z\le {N//3}\), the number of size-2 packs can be any integer from 0 to \(\lfloor({N}-3z)/2\rfloor\); the size-1 count is then forced. Summing \(\lfloor({N}-3z)/2\rfloor+1\) gives \({a}\).',brute,'weighted_packs')
for N in [7,10]:
    a=3*N-3; brute=sum(x+y+z==N and x<=2 and y>=1 for x,y,z in it.product(range(N+1),repeat=3))
    count(rf'An ordered triple of integers \((x,y,z)\) satisfies \(x+y+z={N}\), \(0\le x\le2\), \(y\ge1\), \(z\ge0\). How many triples are possible?',a,[3*N,a+1,a-1,C(N+1,2)],rf'For each fixed \(x=0,1,2\), the positive integer \(y\) has \({N}-x\) choices and \(z\) is determined. The total is \({N}+{N-1}+{N-2}={a}\).',brute,'bounded_first_share')
for n in [7,10]:
    e=n//2;o=n-e;a=C(e,3)+C(o,2)*e;brute=sum(sum(v)%2==0 for v in it.combinations(range(1,n+1),3))
    count(rf'Three different cards are chosen from cards numbered 1 to \({n}\). How many selections have an even total?',a,[C(e,2)*o,a-1,a+1,C(n,3)],rf'An even total uses either three even cards or two odd cards and one even card. There are \({e}\) even and \({o}\) odd cards, so the count is \(\binom{{{e}}}3+\binom{{{o}}}2\,{e}={a}\).',brute,'three_cards_even_sum')
for m in [5,6]:
    # Digits 0,...,m; four-digit even numbers without repetition.
    a=m*(m-1)*(m-2)+(m//2)*(m-1)*(m-1)*(m-2)
    brute=sum(v[0]!=0 and v[-1]%2==0 for v in it.permutations(range(m+1),4))
    count(rf'A four-digit even number is formed without repeated digits using only \(0,1,\ldots,{m}\). How many such numbers can be formed?',a,[a+m,a-m,m*(m-1)*(m-2),2*a],rf'If the last digit is 0, the first three digits can be filled in \({m}({m-1})({m-2})\) ways. There are \({m//2}\) nonzero even choices for the last digit. For each, the first digit has \({m-1}\) nonzero choices and the middle positions have \({m-1}\) then \({m-2}\) choices. The sum is \({a}\).',brute,'even_number_zero')
for n in [4,5]:
    a=sum((-1)**k*C(n,k)*fact(n-k) for k in range(n+1));brute=sum(all(v[i]!=i for i in range(n)) for v in it.permutations(range(n)))
    count(rf'There are \({n}\) labelled envelopes and their \({n}\) matching cards. A card is placed in each envelope. In how many placements is every card in the wrong envelope?',a,[a+1,a-1,fact(n-1),fact(n)-1],rf'Use inclusion–exclusion on the events that particular cards are correctly placed. Specifying a set of \(k\) correct cards leaves \(({n}-k)!\) placements. Therefore the required number is \(\sum_{{k=0}}^{{{n}}}(-1)^k\binom{{{n}}}k({n}-k)!={a}\).',brute,'no_fixed_cards')
for n in [6,7]:
    a=2*fact(n-2)-4*fact(n-3)
    brute=sum((v.index(1) in [1,n-1]) and (abs(v.index(2)-v.index(3)) not in [1,n-1]) for p in it.permutations(range(1,n)) for v in [(0,)+p])
    count(rf'\({n}\) distinct people, including A, B, C and D, sit around a circular table. Rotations are identical; reflections are different. A and B must be adjacent, while C and D must not be adjacent. How many arrangements are possible?',a,[2*fact(n-2),a//2,a+2,a-2],rf'Join A and B into a block. Its internal order has two choices, so there are \(2({n-2})!\) circular arrangements. From these subtract those in which C,D also form a block: \(4({n-3})!\). The difference is \({a}\).',brute,'circular_one_forbidden_pair')
def matchings(xs):
    if not xs:yield [];return
    x=xs[0]
    for i in range(1,len(xs)):
        for rest in matchings(xs[1:i]+xs[i+1:]):yield [(x,xs[i])]+rest
for n in [6,8]:
    total=math.prod(range(1,n,2));bad=math.prod(range(1,n-2,2));a=total-bad;brute=sum((0,1) not in x for x in matchings(list(range(n))))
    count(rf'\({n}\) distinct students are split into pairs. The order of the pairs and the order within a pair do not matter. Two specified students must be in different pairs. How many pairings are possible?',a,[total,bad,a+1,a-1],rf'Pair the first remaining student successively: unrestricted pairings number \(({n-1})({n-3})\cdots1={total}\). If the two specified students are paired together, the other students can be paired in \({bad}\) ways. Subtract to get \({a}\).',brute,'pairings_forbidden_partner')
# The remaining counting constructions occur once each.
perms=set(it.permutations('AABBC'));a=sum('AA' not in ''.join(v) for v in perms)
count('How many different five-letter strings can be made using exactly two As, two Bs and one C, if the two As are not consecutive?',18,[12,24,30,36],r'There are \(5!/(2!2!)=30\) strings without the restriction. Joining the two As into one block gives \(4!/2!=12\) forbidden strings. Thus \(30-12=18\) remain.',a,'multiset_separated_letters')
count(r'Select two vertices of a regular octagon, with no edge joining the selected vertices. How many selections are possible?',20,[8,16,24,28],r'There are \(\binom82=28\) pairs of vertices. Exactly the eight edges are forbidden, giving \(28-8=20\).',sum((j-i) not in [1,7] for i,j in it.combinations(range(8),2)),'polygon_nonneighbours')
def paths(r,u):
    for ps in it.combinations(range(r+u),u):yield tuple(1 if i in ps else 0 for i in range(r+u))
def points(v):
    x=y=0;out=[]
    for z in v:x+=not z;y+=z;out.append((x,y))
    return out
count(r'A path from \((0,0)\) to \((4,3)\) uses only steps one unit right or one unit up. It must not visit \((2,1)\). How many paths are possible?',17,[12,18,23,35],r'All paths number \(\binom73=35\). Those through \((2,1)\) consist of \(\binom31=3\) initial paths and \(\binom42=6\) continuations, so there are 18 forbidden paths. The answer is \(35-18=17\).',sum((2,1) not in points(v) for v in paths(4,3)),'grid_avoid_point')
count(r'A path from \((0,0)\) to \((4,4)\) uses unit right and up steps and never enters \(y>x\). How many paths are possible?',14,[12,28,56,70],r'There are \(\binom84=70\) unrestricted paths. Reflect the initial portion of a forbidden path up to its first step into \(y=x+1\); this bijects forbidden paths with paths having three up and five right steps, of which there are \(\binom83=56\). Thus \(70-56=14\) paths remain.',sum(all(y<=x for x,y in points(v)) for v in paths(4,4)),'grid_diagonal_barrier',d=4)
teams=list(it.combinations(range(7),3));a=sum(len(set(x)&set(y))==2 for x,y in it.product(teams,repeat=2))
count('A group of seven people appoints two named committees, Alpha and Beta, each with three members. Exactly two people serve on both. How many appointments are possible?',420,[210,315,630,840],r'Choose Alpha in \(\binom73=35\) ways. Choose the two shared members from Alpha in three ways, and Beta’s third member from the four outsiders. The committees are named, so no division by two is appropriate. The result is \(35\cdot3\cdot4=420\).',a,'two_named_committees')
count('Four numbered cells are coloured red, blue or green. Every colour is used and cells 1 and 4 have different colours. How many colourings are possible?',30,[24,36,42,54],r'There are \(3\cdot2\cdot3^2=54\) colourings with distinct end colours. For a specified pair of colours, exactly \(2\cdot1\cdot2^2=8\) such colourings use only that pair. There are three pairs, with no overlaps because distinct ends force at least two colours. Subtract \(3\cdot8=24\), leaving 30.',sum(len(set(v))==3 and v[0]!=v[-1] for v in it.product(range(3),repeat=4)),'surjective_colours_distinct_ends')
count(r'How many ordered quadruples of positive odd integers have total 16?',84,[35,56,120,165],r'Write each integer as \(2y_i+1\) with \(y_i\ge0\). Then \(\sum y_i=6\). Six marks separated into four labelled groups require three separators, so the count is \(\binom93=84\).',sum(sum(v)==16 for v in it.product(range(1,16,2),repeat=4)),'four_odd_shares')
count(r'How many ordered triples \((x,y,z)\) satisfy \(x+y+z=8\) with integer coordinates between 0 and 4 inclusive?',15,[12,21,30,45],r'Without upper bounds there are \(\binom{10}2=45\) triples. If a specified coordinate is at least 5, subtracting 5 leaves a sum of 3 and \(\binom52=10\) triples. Two coordinates cannot both reach 5. Thus \(45-3\cdot10=15\).',sum(sum(v)==8 for v in it.product(range(5),repeat=3)),'three_capped_shares')
count(r'How many ordered nonnegative integer triples \((x,y,z)\) have sum 10 and satisfy \(x<y\) and \(x<z\)?',18,[12,15,21,27],r'Fix \(x=a\). The conditions give \(y,z\ge a+1\), so after subtracting these lower bounds the remaining sum is \(8-3a\). The possible values \(a=0,1,2\) contribute respectively 9, 6 and 3 ordered pairs. The total is 18.',sum(x+y+z==10 and x<y and x<z for x,y,z in it.product(range(11),repeat=3)),'specified_strict_minimum')
count('Four married couples are available for a three-person panel. No couple may both serve. How many panels are possible?',32,[24,40,48,56],r'Choose the three represented couples in \(\binom43=4\) ways, then one member from each in \(2^3=8\) ways. The result is 32.',sum(all(not({2*i,2*i+1}<=set(v)) for i in range(4)) for v in it.combinations(range(8),3)),'panel_no_couple')
count('Four designers and four engineers form a five-person panel, with at least two of each profession. How many panels are possible?',48,[24,36,52,56],r'The profession counts are (2,3) or (3,2). Each contributes \(\binom42\binom43=24\); their sum is 48.',sum(sum(i<4 for i in v) in [2,3] for v in it.combinations(range(8),5)),'balanced_profession_panel')
digits=range(7);a=sum(v[0]!=0 and sum(v)%3==0 for v in it.permutations(digits,3))
count(r'How many three-digit multiples of 3 can be written using distinct digits from \(0,1,\ldots,6\)?',a,[a-6,a+6,a//2,84],r'The residue classes modulo 3 have sizes 3,2,2. A three-digit set with sum divisible by 3 is either all in one class or one from each, giving \(\binom33+3\cdot2\cdot2=13\) sets. Each has six orders. Five of these sets contain zero: \(\{0,3,6\}\) and the four choices \(\{0,a,b\}\) with residues 1 and 2. Each such set has two orders starting with zero. Thus \(13\cdot6-5\cdot2=68\).',a,'three_digit_residue_sets')
count('Five distinct books are put on a shelf. Two specified books have exactly one book between them. How many orders are possible?',36,[24,48,60,72],r'The position pair for the specified books can be (1,3), (2,4) or (3,5). Choose their order in two ways, and arrange the remaining books in \(3!=6\) ways. The total is \(3\cdot2\cdot6=36\).',sum(abs(v.index(0)-v.index(1))==2 for v in it.permutations(range(5))),'shelf_exact_gap')
count('A six-position password has exactly two Xs and four Ys. The Xs occupy positions whose sum is odd. How many passwords are possible?',9,[6,8,12,15],r'The two X positions must have opposite parity. Three positions are odd and three even, so the count is \(3\cdot3=9\). Each choice determines the password.',sum((i+j)%2==1 for i,j in it.combinations(range(1,7),2)),'position_sum_parity')
count(r'How many subsets of \(\{1,2,3,4,5,6\}\) contain at least one number from each of the pairs \(\{1,2\},\{3,4\},\{5,6\}\)?',27,[8,18,32,48],r'For each pair, select its first member, its second member or both. These three independent choices across the three pairs give \(3^3=27\).',sum(all(set(v)&set(p) for p in [(1,2),(3,4),(5,6)]) for k in range(7) for v in it.combinations(range(1,7),k)),'cover_disjoint_pairs')
count(r'How many subsets of \(\{1,2,\ldots,8\}\) contain an even number of elements and contain 1?',64,[32,63,65,128],r'After including 1, an odd-sized subset of the other seven elements is needed. Toggling membership of a fixed one of those seven pairs even-sized subsets with odd-sized subsets, so half of their \(2^7\) subsets qualify: 64.',sum(1 in v and k%2==0 for k in range(9) for v in it.combinations(range(1,9),k)),'subset_parity_bijection')
count('A tournament of six teams has every pair play once. Two matches are chosen that share no team. How many choices are possible?',45,[30,60,75,90],r'Choose the four teams involved in \(\binom64=15\) ways. On four fixed teams there are three ways to split them into two unordered pairs. Thus \(15\cdot3=45\).',sum(not(set(x)&set(y)) for x,y in it.combinations(list(it.combinations(range(6),2)),2)),'disjoint_matches')
count('Six numbered boxes each hold either zero or one token. Exactly three tokens are used and box 1 has a token exactly when box 6 has one. How many configurations exist?',8,[6,10,12,16],r'If boxes 1 and 6 both have tokens, choose the remaining token’s box from the four middle boxes. If neither does, choose three of the middle boxes. The two cases give \(4+\binom43=8\).',sum(sum(v)==3 and v[0]==v[-1] for v in it.product([0,1],repeat=6)),'endpoint_equivalence')
count('Five distinct jobs are assigned to two named machines. Each machine must receive at least two jobs; the order of jobs on a machine is ignored. How many assignments are possible?',20,[10,15,24,30],r'The first machine receives either two or three jobs. Therefore there are \(\binom52+\binom53=20\) assignments.',sum(sum(v) in [2,3] for v in it.product([0,1],repeat=5)),'two_machine_load')
count('A string of length five uses the letters A, B and C. It contains exactly one A, and no two Bs are adjacent. How many such strings exist?',45,[35,40,50,55],r'Fix the position of A. In a length-\(m\) run of B/C letters with no adjacent Bs, the counts for \(m=0,1,2,3,4\) are \(1,2,3,5,8\), obtained by separating strings ending in C from those ending in B. The five positions of A contribute \(8,10,9,10,8\), totalling 45.',sum(v.count('A')==1 and 'BB' not in ''.join(v) for v in it.product('ABC',repeat=5)),'single_separator_fibonacci')
count('The digits 1, 2, 3, 4, 5 and 6 are arranged in a row. The three odd digits must appear in increasing order from left to right. How many arrangements are possible?',120,[60,180,240,360],r'Choose the three positions occupied by odd digits in \(\binom63=20\) ways; their order is forced. Arrange the three even digits in \(3!=6\) ways, giving 120.',sum([x for x in v if x%2]==[1,3,5] for v in it.permutations(range(1,7))),'relative_order_constraint')
count('Eight identical counters are placed in four labelled boxes. The first two boxes contain equal numbers, and all counts are nonnegative. How many allocations are possible?',25,[20,24,30,35],r'If the common first-two count is \(a\), the last two counts sum to \(8-2a\). For \(a=0,1,2,3,4\), the numbers of choices are \(9,7,5,3,1\). Their sum is 25.',sum(2*a+b+c==8 for a,b,c in it.product(range(9),repeat=3)),'equal_two_shares')
count('Four distinct prizes are given to three named students. Every student receives at least one prize, and a specified student receives exactly two. How many awards are possible?',12,[6,18,24,36],r'Choose the two prizes for the specified student in \(\binom42=6\) ways. Give the two remaining prizes one each to the other students, in two ways. The count is 12.',sum(v.count(0)==2 and set(v)=={0,1,2} for v in it.product(range(3),repeat=4)),'prizes_specified_double')
count('A six-letter string uses only A and B. It has an even number of As and its first two letters differ. How many strings are possible?',16,[8,12,24,32],r'There are two choices for the first two letters, each containing one A. The last four letters must contain an odd number of As, giving \(\binom41+\binom43=8\) choices. Thus the count is 16.',sum(v[0]!=v[1] and v.count('A')%2==0 for v in it.product('AB',repeat=6)),'prefix_parity')
count('A three-element subset of the integers 1 to 9 is required to have median 5. How many subsets satisfy this?',16,[12,18,20,24],r'The subset must contain 5, one of the four smaller integers and one of the four larger integers. These choices give 16 subsets.',sum(v[1]==5 for v in it.combinations(range(1,10),3)),'fixed_median_selection')
count('Three distinct points are chosen from the vertices of a regular hexagon. How many resulting triangles have no side that is an edge of the hexagon?',2,[3,4,6,8],r'No selected vertices may be adjacent. Around the six-cycle, three selected vertices require at least one unselected vertex in every gap. There are exactly three unselected vertices, so they must alternate with selected vertices. The two alternating triples give two triangles.',sum(all((abs(i-j) not in [1,5]) for i,j in it.combinations(v,2)) for v in it.combinations(range(6),3)),'hexagon_alternating_triangle')
count('Six people are placed in a queue. A is ahead of B, and B is ahead of C. D, E and F have no restrictions. How many queues are possible?',120,[60,180,240,360],r'For any chosen positions of A,B,C their relative order is forced. The other three people may be ordered freely. Thus \(\binom63\,3!=120\).',sum(v.index(0)<v.index(1)<v.index(2) for v in it.permutations(range(6))),'three_person_precedence')
count('A square grid has three rows and four columns of cells. A rectangle is selected whose sides follow grid lines and which consists of an even number of cells. How many rectangles can be selected?',36,[30,40,48,60],r'There are \(\binom42\binom52=60\) rectangles. An odd area requires both an odd height and odd width. Among four horizontal lines there are \(2\cdot2=4\) pairs at odd distance; among five vertical lines there are \(3\cdot2=6\). Hence 24 rectangles have odd area and \(60-24=36\) have even area.',sum((b-a)*(d-c)%2==0 for a,b in it.combinations(range(4),2) for c,d in it.combinations(range(5),2)),'grid_even_area')

# Non-counting miscellaneous problems; the target taxonomy is updated honestly.
add('10_Miscellaneous','Relative speed','round_trip_speed',r'A runner travels 3 km at 6 km/h and returns over the same route at 4 km/h. What is the average speed, in km/h, for the whole journey?',F(24,5),[F(5),F(9,2),F(10,3),F(12,5)],r'The times are \(3/6=1/2\) hour and \(3/4\) hour. Average speed is total distance divided by total time: \(6/(5/4)=24/5\).',F(6)/(F(3,6)+F(3,4)))
add('10_Miscellaneous','Ordering and averages','distinct_integer_range',r'Five distinct positive integers have mean 7 and median 6. What is the largest possible value of the greatest integer?',19,[17,18,20,21],r'The total is 35. To maximise the largest entry, minimise the other four while keeping the third entry 6. They can be \(1,2,6,7\), leaving 19. Any admissible list has its first two entries at least 1 and 2, and its fourth at least 7, so 19 is an attained upper bound.',max(v[-1] for v in it.combinations(range(1,36),5) if sum(v)==35 and v[2]==6))
add('10_Miscellaneous','Deduction','three_switches',r'Exactly one of three switches A, B and C is on. The statements “A is off”, “B is on”, and “C is off” include exactly one true statement. Which switches could be the one that is on?','A or C only',['A only','B only','C only','A, B or C'],r'If A is on, the statements have truth values false, false, true: exactly one is true. If B is on, all three are true. If C is on, they are true, false, false: exactly one is true. Thus both A and C work, so the information does not identify a unique switch.',None)

count(r'Four labelled boxes contain a total of seven identical counters. Exactly one box is empty. How many allocations are possible?',60,[40,48,72,84],r'Choose the empty box in four ways. The other three positive counts sum to 7. Subtracting one from each leaves three nonnegative counts summing to 4, giving \(\binom62=15\) choices. Therefore the total is 60.',sum(sum(v)==7 and v.count(0)==1 for v in it.product(range(8),repeat=4)),'exactly_one_empty_box')
count(r'Four different cards are chosen from cards numbered 1 to 8. The selection must contain exactly two odd cards. How many selections are possible?',36,[24,32,40,48],r'Choose two of the four odd cards and two of the four even cards independently: \(\binom42^2=36\).',sum(sum(vv%2 for vv in v)==2 for v in it.combinations(range(1,9),4)),'specified_parity_composition')
count('A seven-letter palindrome uses only A, B and C and contains exactly three As. How many such palindromes exist?',12,[6,9,18,24],r'The central letter must be A because all other positions occur in matching pairs. Exactly one of the three mirrored pairs is AA, giving three choices. Each other pair is BB or CC, giving \(2^2\) choices. Hence there are 12 palindromes.',sum(v==v[::-1] and v.count('A')==3 for v in it.product('ABC',repeat=7)),'palindrome_odd_frequency')
count(r'A path from \((0,0)\) to \((5,2)\) uses unit right and up steps. The two up steps must not be consecutive. How many paths are possible?',15,[10,12,18,21],r'Write the five right steps first. Their six gaps, including both ends, can each contain at most one up step. Choose two of these gaps: \(\binom62=15\).',sum(all(not(v[i] and v[i+1]) for i in range(6)) for v in paths(5,2)),'isolated_up_steps')
add('10_Miscellaneous','Work rates','alternating_work',r'Machine A completes a job in 6 hours and machine B in 9 hours. They work alternately for one hour each, starting with A, until the job is complete. How many hours does the job take?',F(7),[F(6),F(13,2),F(36,5),F(15,2)],r'Each two-hour cycle completes \(1/6+1/9=5/18\) of the job. Three cycles take 6 hours and complete \(5/6\). A then completes the remaining \(1/6\) in one hour, so the total time is 7 hours.',F(6)+F(1,6)/F(1,6))

S='9_Statistics & Probability'
add(S,'Weighted means','combine_mean_counts',r'Group A has 8 observations with mean 12. Group B has mean 18. The combined mean is 15.6. How many observations are in B?',12,[6,8,10,16],r'If B has \(n\) observations, \(96+18n=15.6(8+n)\). Thus \(2.4n=28.8\), giving \(n=12\). Both group sizes are positive and the result lies between the two original means.',12)
add(S,'Mean and median','replace_order_statistic',r'The ordered data are \(2,4,7,9,t\), where \(t\ge9\). The mean exceeds the median by 1. What is \(t\)?',18,[13,15,16,20],r'The median is the third entry, 7, so the mean is 8. The total must be 40. The four known values total 22, giving \(t=18\), which satisfies \(t\ge9\).',40-22)
add(S,'Frequency means','unknown_frequency',r'The values 1, 4 and 8 occur respectively 4, \(k\) and 2 times, where \(k\) is a positive integer. Their mean is \(11/3\). What is \(k\)?',6,[2,3,4,8],r'The total is \(20+4k\) and the number of values is \(6+k\). From \(3(20+4k)=11(6+k)\), we obtain \(k=6\), a positive integer satisfying the frequency condition.',None)
add(S,'Means after removal','remove_mean_shift',r'Ten numbers have mean 14. Removing two numbers whose mean is 10 leaves eight numbers. What is their mean?',15,[12,13,14,16],r'The original total is 140 and the removed total is 20. The remaining mean is \((140-20)/8=15\).',F(120,8))
add(S,'Conditional probability','dice_conditioned_sum',r'Two fair six-sided dice are rolled. Given that their total is at least 10, what is the probability that the dice show the same number?',F(1,3),[F(1,6),F(1,2),F(2,3),F(1,4)],r'The ordered outcomes with total at least 10 are \((4,6),(5,5),(6,4),(5,6),(6,5),(6,6)\). They are equally likely, and two have equal entries, so the probability is \(2/6=1/3\).',F(sum(x==y and x+y>=10 for x,y in it.product(range(1,7),repeat=2)),sum(x+y>=10 for x,y in it.product(range(1,7),repeat=2))))
add(S,'Sampling without replacement','two_colours_after_discard',r'A bag holds three red and two blue counters. One counter is drawn and discarded without being seen. Two more are then drawn without replacement. What is the probability that these two are of different colours?',F(3,5),[F(2,5),F(1,2),F(3,10),F(7,10)],r'The second and third drawn counters form a uniformly random pair from the original five, irrespective of the unobserved first counter. Six of the ten pairs contain one red and one blue, so the probability is \(6/10=3/5\).',F(sum((v[1]<3)!=(v[2]<3) for v in it.permutations(range(5),3)),60))
add(S,'Conditional probability','choose_bag_posterior',r'A fair coin selects bag A or bag B. Bag A contains two red counters and one blue; bag B contains one red and three blue. One counter is drawn from the selected bag and is red. What is the probability that bag A was selected?',F(8,11),[F(2,3),F(3,4),F(6,11),F(9,11)],r'The probabilities of the joint events are \(P(A\text{ and red})=(1/2)(2/3)=1/3\) and \(P(B\text{ and red})=(1/2)(1/4)=1/8\). Conditional on red, the desired share is \((1/3)/(1/3+1/8)=8/11\).',F(1,3)/(F(1,3)+F(1,8)))
add(S,'Repeated independent trials','first_success_parity',r'A trial succeeds with probability \(1/3\), independently of other trials. Trials continue until the first success. What is the probability that the number of trials is even?',F(2,5),[F(1,3),F(1,2),F(3,5),F(2,3)],r'The probabilities for first success on trials 2,4,6,... sum to \((2/9)(1+4/9+(4/9)^2+\cdots)\). This convergent geometric series is \((2/9)/(1-4/9)=2/5\).',F(2,9)/(1-F(4,9)))

L='8_Logic'
def logical(topic,sub,fam,stem,ans,wrong,sol,d=3):add(topic,sub,fam,stem,ans,wrong,sol,None,d,'Complete logical proof and explicit counterexamples where needed')
logical(L,'Negating quantified statements','quantifier_negation',r'A claim says: “For every positive real \(x\), there is an integer \(n\) such that \(n>x^2\).” Which statement is its logical negation?',r'There is a positive real \(x\) such that every integer \(n\) satisfies \(n\le x^2\).',[r'For every positive real \(x\), every integer \(n\) satisfies \(n\le x^2\).',r'There is a positive real \(x\) and an integer \(n\) with \(n\le x^2\).',r'For every integer \(n\), there is a positive real \(x\) with \(n\le x^2\).',r'There is an integer \(n\) such that every positive real \(x\) satisfies \(n>x^2\).'],r'Negation changes the outer “for every” to “there exists” and the inner “there exists” to “for every”. The negation of \(n>x^2\) is \(n\le x^2\). The order of the quantified variables is preserved.')
logical(L,'Necessary and sufficient conditions','reciprocal_condition',r'Let \(x\) be a nonzero real number. Relative to the condition \(x+1/x\ge2\), the condition \(x>0\) is:', 'Both necessary and sufficient',['Necessary but not sufficient','Sufficient but not necessary','Neither necessary nor sufficient','Impossible to satisfy'],r'For \(x>0\), \(x+1/x-2=(x-1)^2/x\ge0\). For \(x<0\), both \(x\) and \(1/x\) are negative, so their sum is below 2. Thus the two conditions are equivalent.')
logical(L,'Implication between functions','composition_injectivity',r'Functions \(g:A\to B\) and \(f:B\to C\) have an injective composition \(f\circ g\). Which conclusion must follow?','g is injective',['f is injective','g is surjective','f is surjective','Both f and g are surjective'],r'If \(g(a)=g(b)\), applying f gives \(f(g(a))=f(g(b))\), so injectivity of the composition implies \(a=b\). The other claims need not hold: let \(A=\{1\},B=\{1,2\},C=\{1,2\}\), let g(1)=1 and let f be constantly 1. The composition on the singleton A is injective, but f is not injective or surjective and g is not surjective.')
logical(L,'Counterexamples','strict_square_inequality',r'Which value of \(x\) disproves the assertion “If \(x^2>x\), then \(x>1\)”?',r'\(-2\)',[r'\(0\)',r'\(1/2\)',r'\(1\)',r'\(2\)'],r'A counterexample must make the premise true and the conclusion false. At \(x=-2\), \(4>-2\) is true while \(-2>1\) is false. At 0, 1/2 and 1 the premise fails, while at 2 the conclusion holds.')
logical(L,'Parity and equivalence','parity_product',r'For integers \(a,b\), which condition is equivalent to “\(a+b\) is odd”?','Exactly one of a and b is odd',['Both a and b are odd','At least one of a and b is odd','ab is odd','a and b have the same parity'],r'Modulo 2, the sum is 1 precisely for the residue pairs (0,1) and (1,0). Both-odd gives an even sum, while “at least one odd” also includes the both-odd case. The product is odd only in that excluded case.')
logical(L,'Even and odd functions','even_and_odd_zero',r'A real-valued function on all real numbers satisfies \(f(-x)=f(x)\) and \(f(-x)=-f(x)\) for every real \(x\). Which conclusion is forced?',r'\(f(x)=0\) for every real \(x\)',[r'\(f(x)=x\) for every real \(x\)',r'\(f(x)=1\) for every real \(x\)',r'f has exactly one zero',r'f has no zeros'],r'The two identities imply \(f(x)=-f(x)\), hence \(2f(x)=0\) at every x. Thus f is identically zero; the assertion does not merely establish f(0)=0.')
logical(L,'Finite-set functions','finite_surjection',r'A function maps a set of five elements to a set of five elements, and every element of the second set is attained. Which must be true?','Each output has exactly one input',['Some output has two inputs','The function is constant','Every input is its own output','Exactly one output is unused'],r'There are five inputs and five nonempty output fibres. Their sizes are positive integers adding to five, so all five sizes must be one. The sets need not even have matching labels, so being an identity function is not forced.')
logical(L,'Trigonometric implications','cosine_sine_condition',r'For real \(x\), consider P: \(\cos x=1\), and Q: \(\sin x=0\). Which description is correct?','P implies Q, but Q does not imply P',['Q implies P, but P does not imply Q','P and Q are equivalent','Neither condition implies the other','P and Q cannot both hold'],r'If \(\cos x=1\), the identity \(\sin^2x+\cos^2x=1\) forces \(\sin x=0\). The converse fails at \(x=\pi\), where sine is zero and cosine is −1.')
logical(L,'Logic of inequalities','interval_complement',r'For real \(x\), which condition is equivalent to \(x^2>x\)?',r'\(x<0\) or \(x>1\)',[r'\(0<x<1\)',r'\(x<1\)',r'\(x>0\)',r'\(x\ne0\) and \(x\ne1\)'],r'Factor the inequality as \(x(x-1)>0\). The two factors have the same strict sign precisely when both are negative, giving x<0, or both are positive, giving x>1. The endpoints and the interval between them fail.')
logical(L,'Logical deductions','subset_inclusion_chain',r'Every element of set A is in B. No element of B is in C. Which conclusion is necessarily true?','No element of A is in C',['Every element of C is in A','Every element of B is in A','A is empty','C is empty'],r'An element of A would lie in B; it therefore cannot lie in C. Nonempty disjoint sets A and C with A properly contained in B show that the other statements are not forced.')
logical(L,'Counterexamples involving sequences','positive_start_nonmonotone',r'The recurrence \(u_{n+1}=2-u_n\) has \(u_1=3\). Which claim about the sequence is true?','The sequence alternates between 3 and −1',['Every term is positive','The sequence is strictly increasing','The sequence eventually becomes constant','Every term is at most 2'],r'The recurrence gives \(u_2=-1\), \(u_3=3\), and applying it twice returns any starting value: \(2-(2-u_n)=u_n\). Hence the period is exactly two and the two values are 3 and −1.')
logical(L,'Necessary conditions','remainder_equivalence',r'For an integer \(n\), which condition is equivalent to “\(n^2\) leaves remainder 1 on division by 3”?','n is not divisible by 3',['n is odd','n leaves remainder 1 on division by 3','n leaves remainder 2 on division by 3','n is positive'],r'The three possible remainders of n modulo 3 are 0,1,2; their squares have remainders 0,1,1 respectively. Thus either nonzero remainder, and only those, gives remainder 1.')

P='11_Proofs'
logical(P,'Divisibility','odd_square_mod8',r'For an odd integer \(n\), which integer must divide \(n^2-1\)?',8,[3,5,7,9],r'Write \(n=2k+1\). Then \(n^2-1=4k(k+1)\). One of consecutive integers k,k+1 is even, so this is divisible by 8. At n=3 the expression is 8, showing that none of 3,5,7,9 is guaranteed.')
logical(P,'Consecutive integers','three_consecutive_product',r'Which expression is divisible by 6 for every integer \(n\)?',r'\(n(n+1)(n+2)\)',[r'\(n^2+1\)',r'\(n(n+2)\)',r'\(n^3+1\)',r'\(3n^2+3\)'],r'Among three consecutive integers there is a multiple of 3 and at least one even integer, so their product is divisible by 6. For the alternatives, n=0 gives 1 for the first, n=1 gives 3 for the second, n=0 gives 1 for the third, and n=0 gives 3 for the fourth.')
logical(P,'Reversible operations','division_zero_loss',r'A student solves \(x(x-3)=0\) by dividing by \(x\) and obtaining \(x=3\). What is the precise defect?','Division by x excludes the possible solution x=0',['The factor x−3 cannot be negative','The equation has no real solutions','Division by x always reverses an equality','The value x=3 is extraneous'],r'Division by x is valid only when x≠0. The omitted case x=0 satisfies the original equation. The correct solution set is {0,3}; x=3 is a valid but incomplete result.')
logical(P,'Squaring equations','extraneous_root',r'When solving \(\sqrt{x+4}=x-2\), a student squares both sides and finds \(x=0\) or \(x=5\). Which statement is correct?','Only x=5 satisfies the original equation',['Both values satisfy the original equation','Only x=0 satisfies the original equation','Neither value is real','Squaring guarantees all resulting roots are valid'],r'The right-hand side must be nonnegative, hence x≥2. Squaring gives \(x+4=(x-2)^2\), or \(x(x-5)=0\). The domain discards 0. Direct substitution at 5 gives \(\sqrt9=3\), so 5 is valid.')
logical(P,'Uniqueness by factorisation','strict_cubic_map',r'If real numbers \(a,b\) satisfy \(a^3+a=b^3+b\), which conclusion follows?',r'\(a=b\)',[r'\(a=-b\) and \(a\ne0\)',r'\(a+b=1\)',r'\(ab=-1\)',r'\(|a-b|=1\)'],r'Subtract and factor: \((a-b)(a^2+ab+b^2+1)=0\). The second factor equals \((a+b/2)^2+3b^2/4+1\), which is strictly positive. Therefore the first factor must vanish.')
logical(P,'Contrapositive','contrapositive_divisibility',r'What is the contrapositive of “If an integer is divisible by 12, then it is divisible by 4”?','If an integer is not divisible by 4, it is not divisible by 12',['If an integer is divisible by 4, it is divisible by 12','If an integer is not divisible by 12, it is not divisible by 4','Every integer is divisible by 4 or 12','No integer is divisible by both 4 and 12'],r'The contrapositive of P⇒Q is ¬Q⇒¬P. Here P is divisibility by 12 and Q is divisibility by 4. The converse and inverse are different statements and fail, for example, at 4.')
logical(P,'Proof by contradiction','irrational_translation',r'Let \(r\) be irrational and \(q\) rational. Which statement must hold?',r'\(r+q\) is irrational',[r'\(rq\) is irrational',r'\(r^2\) is irrational',r'\(r-q\) is rational',r'\(r/q\) is a defined irrational number'],r'If r+q were rational, subtracting the rational q would make r rational, a contradiction. Multiplication or division claims fail at q=0 (division is undefined). Squaring can yield a rational value, as for r=√2. Also r−q is irrational by the same subtraction argument.')
logical(P,'Counterexample to converse','square_product_converse',r'The claim “If \(ab\) is a perfect square for positive integers \(a,b\), then both \(a\) and \(b\) are perfect squares” is false. Which pair is a counterexample?',r'\((2,8)\)',[r'\((4,9)\)',r'\((2,3)\)',r'\((1,4)\)',r'\((3,5)\)'],r'The product 2·8=16 is a square, while neither factor is a square. The pairs (4,9) and (1,4) satisfy the conclusion, and the other two pairs have nonsquare products, so cannot refute the implication.')
logical(P,'Bounds and equality','two_variable_lower_bound',r'For positive real \(x,y\) with \(xy=9\), what is the smallest possible value of \(x+y\)?',6,[3,4,9,18],r'From \((x-y)^2\ge0\), \((x+y)^2\ge4xy=36\). Positivity gives x+y≥6. Equality is attained at x=y=3, so the bound is the exact minimum.')
logical(P,'Quantifiers and witnesses','polynomial_zero_quantifiers',r'Which statement is true?',r'There exists a real \(a\) such that every real \(x\) satisfies \((x-a)^2\ge0\).',[r'There exists a real \(a\) such that every real \(x\) satisfies \((x-a)^2>0\).',r'Every real \(a\) admits a real \(x\) with \((x-a)^2<0\).',r'Every real \(x\) satisfies \(x^2>x\).',r'There exists a real \(a\) such that every real \(x\) satisfies \(x>a\).'],r'For the correct statement, choose a=0: every real square is nonnegative. The strict-square statement fails at x=a; a negative square is impossible; x²>x fails at x=0; and the claimed universal lower bound fails at x=a.')
logical(P,'Logical truth conditions','exactly_two_statements',r'A positive integer \(n<10\) makes exactly two of these statements true: I: \(n\) is even; II: \(n\) is divisible by 3; III: \(n>6\). How many values of \(n\) are possible?',3,[1,2,4,5],r'Check the finite domain 1 to 9. The numbers 6,8,9 give truth patterns (true,true,false), (true,false,true), (false,true,true), respectively. All other values give at most one true statement. Thus there are three.')
logical(P,'Necessary and sufficient conditions','quadratic_discriminant_logic',r'For real \(k\), the equation \(x^2-2kx+k+2=0\) has two distinct real roots exactly when:',r'\(k<-1\) or \(k>2\)',[r'\(-1<k<2\)',r'\(k\le-1\) or \(k\ge2\)',r'\(k>0\)',r'\(k\ne-1\) and \(k\ne2\)'],r'Two distinct real roots are equivalent to a strictly positive discriminant. Here it is \(4k^2-4k-8=4(k-2)(k+1)\), which is positive outside [−1,2]. Equality at the endpoints gives repeated roots, so they are excluded.')
logical(P,'Valid and invalid implications','sum_square_zero',r'Let \(a,b\) be real. Which implication is valid?',r'If \(a^2+b^2=0\), then \(a=b=0\).',[r'If \(a+b=0\), then \(a=b=0\).',r'If \(ab=0\), then \(a=b=0\).',r'If \(a^2=b^2\), then \(a=b\).',r'If \(a^2+b^2=1\), then \(a+b=1\).'],r'Both squares are nonnegative, so a zero sum forces each to be zero. Counterexamples for the other claims are respectively (1,−1), (0,1), (1,−1), and (−1,0).')
logical(P,'Divisibility equivalence','coprime_factors',r'For an integer \(n\), which condition is equivalent to \(6\mid5n\)?',r'\(6\mid n\)',[r'\(5\mid n\)',r'\(2\mid n\)',r'\(3\mid n\)',r'\(30\mid n\)'],r'If 6 divides n, it divides 5n. Conversely, 5n divisible by 6 is both even and divisible by 3. Since 5 is odd and is not divisible by 3, n must be even and divisible by 3. Therefore 6 divides n. Divisibility by 30 is stronger than necessary.')
logical(P,'Monotonicity of roots','cube_root_order',r'For real \(x\), which condition is equivalent to \(\sqrt[3]{2x-1}>\sqrt[3]{x+5}\)?',r'\(x>6\)',[r'\(x>3\)',r'\(x<6\)',r'\(x\ge6\)',r'\(x>0\)'],r'The real cube function is strictly increasing: if u>v, then \(u^3-v^3=(u-v)(u^2+uv+v^2)>0\). Thus comparison of real cube roots is equivalent to comparison of radicands. We obtain 2x−1>x+5, or x>6. No nonnegative-radicand restriction is needed for cube roots.')
logical(P,'Contradiction and parity','odd_even_equation',r'Which equation has no solution in integers \(x,y\)?',r'\(2x+4y=7\)',[r'\(2x+3y=7\)',r'\(3x+4y=7\)',r'\(2x+4y=8\)',r'\(3x+6y=9\)'],r'The left side 2x+4y is always even but 7 is odd, a contradiction. The other equations have solutions (x,y)=(2,1),(1,1),(4,0),(3,0), respectively.')
logical(P,'Algebraic equivalence','rational_domain_proof',r'For real \(x\), which is the complete solution set of \((x^2-4)/(x-2)=4\)?','The empty set',[r'\(\{2\}\)',r'\(\{-2\}\)',r'\(\{-2,2\}\)','All real numbers except 2'],r'The expression is defined only for x≠2. On that domain it simplifies to x+2, so the equation would require x=2. That sole candidate is excluded by the original denominator, leaving no solution.')
logical(P,'Deduction from disjunction','exclusive_logic',r'Exactly one of P and Q is true. The implication \(P\Rightarrow R\) is true, and R is false. What must be true?','Q is true',['P is true','Q is false','P and Q are both false','R is true'],r'If P were true, the valid implication would make R true, contrary to the given fact. Thus P is false. Exactly one of P,Q is true, so Q must be true.')
logical(P,'Proof of an integer bound','least_integer_square_bound',r'An integer \(n\ge0\) satisfies \(n^2<3n+18\). What is the greatest possible \(n\)?',5,[3,4,6,7],r'Rearrange as \((n-6)(n+3)<0\). Since n≥0 makes n+3 positive, the inequality is equivalent to n<6. The greatest admissible integer is 5, and \(25<33\) verifies it.')

def save():
    (ROOT/'reasoning_questions.json').write_text(json.dumps(out,indent=2,ensure_ascii=False))
    assert all(not v for v in buckets.values()),{k:len(v) for k,v in buckets.items()}
    assert len(out)==93
    (ROOT/'reasoning_validation.json').write_text(json.dumps({'count':len(out),'family_count':len(set(x['family'] for x in out)),'remaining':{k:len(v) for k,v in buckets.items()},'status':'checked'},indent=2))
if __name__=='__main__':save()
